#include "score_pages.h"

#include "frame_format.h"   // parse_authored_frame: the canonical digits

#include <algorithm>
#include <fstream>
#include <iterator>
#include <string_view>
#include <system_error>

namespace {

// The grammar's fixed header line (tools/score_extract.py's head), byte for
// byte as the tool writes it.
constexpr std::string_view kGeneratedLine =
    "# generated by tools/score_extract.py; frames at `rate`, begin "
    "inclusive, end exclusive";

// A canonical non-negative decimal, the frame grammar's own spelling (no
// sign, no point, no leading zero, int64 overflow refused) — the tool writes
// Python's `str` of an int, which is exactly that.
bool parse_count(std::string_view text, int64_t& out) {
    return parse_authored_frame(std::string(text), out);
}

std::string line_error(int ln, const std::string& words) {
    return "line " + std::to_string(ln) + ": " + words;
}

}  // namespace

std::filesystem::path GuiScorePages::page_file(int i) const {
    // The tool's page_name: the number padded to max(3, the count's digits).
    const std::size_t width = std::max<std::size_t>(
        3, std::to_string(count()).size());
    std::string number = std::to_string(i + 1);
    if (number.size() < width) number.insert(0, width - number.size(), '0');
    return folder / ("page" + number + ".png");
}

std::filesystem::path score_folder_of(const std::filesystem::path& project_folder,
                                      const std::string&           score_path) {
    if (score_path.empty()) return {};
    return (project_folder / std::filesystem::path(score_path))
        .lexically_normal();
}

std::expected<GuiScoreRead, std::string> read_score_folder(
        const std::filesystem::path& folder) {
    GuiScoreRead out;
    std::error_code ec;
    if (!std::filesystem::is_directory(folder, ec)) {
        out.advisory = "No score folder at '" + folder.string() + "'";
        return out;
    }
    const std::filesystem::path txt = folder / "pages.txt";
    std::ifstream f(txt, std::ios::binary);
    if (!f) {
        out.advisory = "No readable pages.txt in '" + folder.string() + "'";
        return out;
    }
    const std::string bytes{std::istreambuf_iterator<char>(f),
                            std::istreambuf_iterator<char>()};
    if (f.bad()) {
        out.advisory = "Could not read '" + txt.string() + "'";
        return out;
    }

    // LF LINE ENDS: every line, the last included, ends in '\n'; no other
    // control byte stands anywhere. ASCII but for the `# src` line's free
    // text (score_pages.h's head).
    if (bytes.empty()) return std::unexpected(std::string("the file is empty"));
    if (bytes.back() != '\n')
        return std::unexpected(std::string("the last line has no line end"));
    std::vector<std::string_view> lines;
    {
        std::string_view rest(bytes);
        while (!rest.empty()) {
            const std::size_t nl = rest.find('\n');
            lines.push_back(rest.substr(0, nl));
            rest.remove_prefix(nl + 1);
        }
    }
    for (std::size_t i = 0; i < lines.size(); ++i) {
        for (const char ch : lines[i]) {
            const unsigned char u = static_cast<unsigned char>(ch);
            if (u < 0x20 || u == 0x7f)
                return std::unexpected(line_error(static_cast<int>(i) + 1,
                                                  "a control byte"));
        }
    }

    GuiScorePages table;
    table.folder = folder;
    std::size_t at = 0;
    const auto ln = [&] { return static_cast<int>(at) + 1; };
    const auto header_is = [&](std::string_view prefix) {
        return at < lines.size() && lines[at].starts_with(prefix);
    };
    // THE HEADER, in its order: `# src`, an optional `# url`, `# rate`, the
    // generated line.
    if (!header_is("# src ") || lines[at].size() == 6)
        return std::unexpected(line_error(ln(), "not the '# src' line"));
    ++at;
    if (header_is("# url ")) {
        const std::string_view link = lines[at].substr(6);
        if (link.empty() || link.find(' ') != std::string_view::npos)
            return std::unexpected(line_error(ln(), "not one link"));
        ++at;
    }
    if (!header_is("# rate "))
        return std::unexpected(line_error(ln(), "not the '# rate' line"));
    if (!parse_count(lines[at].substr(7), table.rate) || table.rate <= 0)
        return std::unexpected(line_error(ln(), "the rate is not a positive "
                                                "integer"));
    ++at;
    if (at >= lines.size() || lines[at] != kGeneratedLine)
        return std::unexpected(line_error(ln(), "not the 'generated by' line"));
    ++at;

    // THE PAGES: `<page>|<begin>|<end>`, numbered 1, 2, 3 … in line order,
    // begin under end, each begin at or past its predecessor's end.
    if (at >= lines.size())
        return std::unexpected(std::string("no page"));
    for (; at < lines.size(); ++at) {
        const std::string_view line = lines[at];
        const std::size_t p1 = line.find('|');
        const std::size_t p2 = p1 == std::string_view::npos
                                   ? std::string_view::npos
                                   : line.find('|', p1 + 1);
        if (p2 == std::string_view::npos ||
            line.find('|', p2 + 1) != std::string_view::npos)
            return std::unexpected(line_error(ln(), "not a page line"));
        int64_t number = 0;
        GuiScorePage page;
        if (!parse_count(line.substr(0, p1), number) ||
            !parse_count(line.substr(p1 + 1, p2 - p1 - 1), page.begin) ||
            !parse_count(line.substr(p2 + 1), page.end))
            return std::unexpected(line_error(ln(), "not a page line"));
        const int64_t want = static_cast<int64_t>(table.pages.size()) + 1;
        if (number != want)
            return std::unexpected(line_error(
                ln(), "page " + std::to_string(number) + " where page " +
                          std::to_string(want) + " belongs"));
        if (page.begin >= page.end)
            return std::unexpected(line_error(
                ln(), "page " + std::to_string(number) +
                          "'s begin is not under its end"));
        if (!table.pages.empty() && page.begin < table.pages.back().end)
            return std::unexpected(line_error(
                ln(), "page " + std::to_string(number) +
                          " overlaps the page before it"));
        table.pages.push_back(page);
    }

    // EVERY PAGE'S FILE, stat'ed (the head): the first one missing is the
    // refusal, named by its page line.
    const int header_lines = static_cast<int>(lines.size()) - table.count();
    for (int i = 0; i < table.count(); ++i) {
        const std::filesystem::path png = table.page_file(i);
        if (!std::filesystem::is_regular_file(png, ec))
            return std::unexpected(line_error(
                header_lines + i + 1,
                "no '" + png.filename().string() + "' beside it"));
    }
    out.pages = std::move(table);
    return out;
}
